// G-27: the picker's emoji list (docs/ux/specs/emoji-picker.md §2–3). The data
// is generated by scripts/build-emoji.mjs (Unicode + CLDR, filtered through
// normalizeEmoji) and loaded on the first open, then kept.

import { normalizeEmoji } from '../core/emoji';

export const GROUPS = ['smileys', 'people', 'nature', 'food', 'travel', 'activities', 'objects', 'symbols', 'flags'] as const;
export type Group = (typeof GROUPS)[number];

export interface EmojiEntry {
  /** What's shown and inserted (fully qualified, with VS16 where Unicode has it). */
  glyph: string;
  /** The reaction form (`normalizeEmoji`): the key for recent and "mine". */
  key: string;
  group: Group;
  en: string;
  he: string;
  /** Folded words of both names and both keyword lists, for search. */
  words: string[];
}

export interface EmojiData {
  list: EmojiEntry[];
  byKey: Map<string, EmojiEntry>;
}

type Raw = { groups: string[]; emoji: [string, number, string, string, string, string][] };

/** Lower case, without niqqud, accents or other combining marks. */
export function fold(s: string): string {
  return s.normalize('NFKD').replace(/\p{M}/gu, '').toLowerCase();
}

export function words(s: string): string[] {
  return fold(s)
    .split(/[^\p{L}\p{N}]+/u)
    .filter(Boolean);
}

export function buildData(raw: Raw): EmojiData {
  const list: EmojiEntry[] = [];
  for (const [glyph, g, en, enKw, he, heKw] of raw.emoji) {
    const key = normalizeEmoji(glyph);
    const group = raw.groups[g] as Group | undefined;
    if (!key || !group || !GROUPS.includes(group)) continue;
    list.push({ glyph, key, group, en, he: he || en, words: [...new Set(words(`${en} ${enKw} ${he} ${heKw}`))] });
  }
  return { list, byKey: new Map(list.map((e) => [e.key, e])) };
}

let loading: Promise<EmojiData> | null = null;

export function loadEmoji(): Promise<EmojiData> {
  loading ??= import('./data.json').then((m) => buildData((m.default ?? m) as unknown as Raw));
  return loading;
}

/** Every word of the query starts some word of the name or keywords, in either language. */
export function search(data: EmojiData, query: string): EmojiEntry[] {
  const q = words(query);
  if (!q.length) return [];
  return data.list.filter((e) => q.every((w) => e.words.some((x) => x.startsWith(w))));
}
